using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Geometry;

internal sealed class BiasedBoundaryHeatDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Geometry/BiasedBoundaryHeat.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The original real centered boundary space G0 carries a spectral heat semigroup whose generator is exactly minus the original boundary operator on its entire centered domain.",
        H("Real Heat of the Actual Centered Boundary Operator"), Blocks(
            Describe.Lean(DescribeId.Create("biasedboundaryheat-definition"),
                DeclarationHandle.Create(Prefix + "heat"), H("The Real Heat Multiplier"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For a real Hilbert basis e of the original G0 and positive covariance eigenvalues mu, heat(e,mu,t) transports the bounded coordinate multipliers exp(-t/mu(i)) through e.repr. Time t is nonnegative. The map acts on every vector of G0; it does not replace that space by finite sequences."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("biasedboundaryheat-full"),
                DeclarationHandle.Create(Prefix + "fullHeat"), H("The Ambient Heat"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("On the original ambient G, fullHeat fixes constG(mean(F)) and applies centered heat to the orthogonal centered part Pi(F), included isometrically back into G. It uses the original real carriers and the same covariance sequence."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("biasedboundaryheat-generator"),
                DeclarationHandle.Create(Prefix + "actual_heat"), H("The Actual Heat, Trace and Generator"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("One application of the actual spectral counting theorem supplies paired bases e on G0 and k on the effective edge space K, together with one positive nonincreasing covariance sequence mu tending to zero. The original Sigma and ambient C have their actual paired diagonal actions on this same family. The original source centeredTrace with codomain G0 has the same paired action before inclusion. Its composition with the actual isometric inclusion G0 into G equals ambient C, and centeredTrace adjoint composed with centeredTrace is literally Sigma on the entire original edge carrier. Every repeated eigenvalue keeps its own basis occurrence.")),
                    Paragraph(Text("The transported heat operators form a strongly continuous contraction semigroup. They are positive, and their intrinsic extended positive trace is the sum of ofReal(exp(-t/mu(i))) for every nonnegative t. The formula also holds at time zero as an extended value. At every positive time the series is summable and the intrinsic positive trace is finite. The real trace value is the toReal of this proved finite extended trace.")),
                    Paragraph(Text("For all centered vectors u and v, the strong limit at time zero from the right of t inverse times (S(t)u-u) equals v if and only if (u,-v) lies in the original boundaryOperator graph after the original isometric inclusion into G. The parameterized polar graph and coefficient identities apply to the same e,k,mu and give the exact all-vector coefficient graph. Continuous coefficient functionals prove one direction. Finite basis projections of both the vector and its original graph image, followed by the real semigroup generator-limit theorem, prove the reverse direction.")),
                    Paragraph(Text("Any other strongly continuous contraction semigroup with this same full generator graph equals S. The multiplier, finite-span continuity and uniqueness design reuse the standard construction in DiagonalHeat and the attributed MarkovProcess supplies in ContractionSemigroup. No self-adjoint realization, inverse-domain, spectral exhaustion or counting proof is repeated.")),
                    Paragraph(Text("The ambient heat is also a strongly continuous positive contraction semigroup, with the strong generator equal to minus the original boundaryOperator on every vector in its exact domain. It uniquely has that generator. Its restriction to the original G0 is the centered heat, and it fixes every original constant. A complete orthonormal basis consisting of constG(1) and the included centered basis proves that its intrinsic trace is exactly one plus the centered trace, with exactly one added constant mode.")),
                    Paragraph(Text("For every s>0 the centered trace lies between (b/s) exp(-s/b) and B/s, with b=phi to the power minus two and B=2 phi cubed. When 0<s<=b, its lower bound is b/(exp(1) s), including equality in the time cutoff. The proof compares the same ordered reciprocal eigenvalues with shifted geometric exponentials. Their summability is established before using real infinite sums or the toReal trace.")),
                    Paragraph(Text("The inclusive finite cutoff count equals the sum of inclusive mode indicators, counting every repeated occurrence. The Laplace identity is proved with the original positiveCount: the centered trace is s times the integral on u>0 of exp(-s u) Nplus(u). Each indicator tail is integrable; the norms of their integrals have a summable series. Interchanging sum and integral is therefore justified, and the closed tail endpoint has zero Lebesgue measure.")),
                    Paragraph(Text("The logarithm of the inclusive positive count divided by log(lambda) tends to one at infinity. The logarithm of the original one-based eigenvalue divided by log(j) also tends to one. The centered and ambient heat logarithms divided by log(1/s) tend to one from positive times at zero. The proof squeezes each quotient between positive constant multiples with the same diverging logarithmic denominator. It asserts no Weyl coefficient or additive counting remainder.")),
                    Paragraph(Text("The separate operator approximation-number/singular-value correspondence, Schatten classes and equivalence of finite intrinsic positive trace with trace class remain open. In particular this delivery does not assert the full original Theorem 3.1 or its covariance ideal corollary. Sigma, rather than C, is the object of the source Hilbert-Schmidt assertion. The original C has centered codomain G0. Its precise ambient inclusion and Gram equality are proved here; the full-carrier singular-value correspondence remains open."))), DescribeRole.Theorem))));
}
